import{_ as a,C as r,o as n,c as d,j as t,a as o,E as i,a7 as l}from"./chunks/framework.C4ZIv4ii.js";const f=JSON.parse('{"title":"News Sites","description":"","frontmatter":{},"headers":[],"relativePath":"guide/news.md","filePath":"guide/news.md","lastUpdated":1792509062000}'),h={name:"guide/news.md"},c={id:"news-sites",tabindex:"-1"};function g(u,e,p,w,m,y){const s=r("Badge");return n(),d("div",null,[t("h1",c,[e[0]||(e[0]=o("News Sites ",-1)),i(s,{type:"warning",text:"Pro"}),e[1]||(e[1]=o()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#news-sites","aria-label":'Permalink to "News Sites <Badge type="warning" text="Pro" />"'},"​",-1))]),e[3]||(e[3]=l('<p>The <strong>Falcon News</strong> plugin adds what a news or magazine site needs on top of posts and categories: a view counter with Most Read lists, view counts anywhere in the builder, RSS feeds and a Google News sitemap.</p><p>It ships with <a href="/falconcms/guide/pro.html">FalconCMS Pro</a> and needs FalconCMS 2.8.5 or later. Activate it under <strong>Plugins</strong>. It has no menu of its own; its screens sit where you would look for them:</p><table tabindex="0"><thead><tr><th>What</th><th>Where</th></tr></thead><tbody><tr><td>Most viewed stories, and the view counter&#39;s settings</td><td><strong>Analytics → Most Viewed</strong></td></tr><tr><td>RSS feeds</td><td><strong>Settings → RSS Feeds</strong></td></tr><tr><td>Google News sitemap</td><td><strong>SEO → Settings → Google News sitemap</strong></td></tr></tbody></table><p>For your Instagram posts, see the <a href="/falconcms/guide/instagram-feed.html">Instagram Feed</a> builder element.</p><h2 id="the-view-counter" tabindex="-1">The view counter <a class="header-anchor" href="#the-view-counter" aria-label="Permalink to &quot;The view counter&quot;">​</a></h2><p>Every time a reader opens a story, it is counted. <strong>Analytics → Most Viewed</strong> lists the top stories today, in the last 7 days, the last 30 days and of all time.</p><ul><li><strong>It works with the page cache and behind Cloudflare.</strong> The story page reports the view once it has loaded, so a cached page counts like any other.</li><li><strong>Bots are left out.</strong> Search engines and monitors that do not run scripts never count, and known bots are filtered by name too.</li><li><strong>A reload is not a new reader.</strong> A visitor counts once per story every 30 minutes.</li><li><strong>Your own team is left out.</strong> Signed-in visitors are not counted unless you switch that on.</li></ul><p>Open <strong>Counter settings</strong> on the Most Viewed page to choose which post types are counted, the time before the same reader counts again, whether signed-in visitors count, and how many days of daily figures are kept (the all-time count of each story is kept for ever). Each counted post type gets a <strong>Views</strong> column in its admin list, with the last 7 days beside the total.</p><h3 id="most-read-and-trending-boxes" tabindex="-1">Most Read and Trending boxes <a class="header-anchor" href="#most-read-and-trending-boxes" aria-label="Permalink to &quot;Most Read and Trending boxes&quot;">​</a></h3><p>Add a <strong>Card</strong> element and set <strong>Order By</strong> to one of:</p><table tabindex="0"><thead><tr><th>Order By</th><th>Shows</th></tr></thead><tbody><tr><td>Views</td><td>the most read stories of all time</td></tr><tr><td>Views — today</td><td>today&#39;s most read</td></tr><tr><td>Views — last 7 days</td><td>this week&#39;s trending stories</td></tr><tr><td>Views — last 30 days</td><td>this month&#39;s most read</td></tr></tbody></table><p>Combine it with <strong>Posts By → Categories</strong> for a &quot;Most read in Sports&quot; box.</p><h3 id="showing-a-story-s-view-count" tabindex="-1">Showing a story&#39;s view count <a class="header-anchor" href="#showing-a-story-s-view-count" aria-label="Permalink to &quot;Showing a story&#39;s view count&quot;">​</a></h3><p>Any title, text block or button can show the count through <strong>dynamic content</strong>: click the database icon, choose <strong>Post Views</strong>, then pick:</p><ul><li><strong>Period</strong>: all time, today, last 7 or 30 days.</li><li><strong>Number</strong>: <code>12,345</code>, <code>12.3K</code> or <code>12345</code>.</li><li><strong>Label</strong>: the words after the number (<code>views</code>), or around it with <code>{count}</code>: <code>Read {count} times</code>.</li><li><strong>Digits</strong>: Latin, Bangla (<code>১২৩</code>), Devanagari or Arabic.</li><li><strong>Hide below</strong>: show the fallback text instead until a story has this many views.</li></ul><p>It works on a single post layout and in each card of a Card grid. In text you can also type the token <code>{lazy:post_views}</code>.</p><h2 id="reading-time" tabindex="-1">Reading time <a class="header-anchor" href="#reading-time" aria-label="Permalink to &quot;Reading time&quot;">​</a></h2><p>The <strong>Reading Time</strong> dynamic source (and the Post Meta element) counts words in any language, and in posts made with the builder. Choose its label (<code>min read</code>, or <code>{min} minute read</code>), the reading speed and the digits.</p><h2 id="showing-a-lead-story" tabindex="-1">Showing a lead story <a class="header-anchor" href="#showing-a-lead-story" aria-label="Permalink to &quot;Showing a lead story&quot;">​</a></h2><p>To pick stories by hand, add a custom field (a checkbox or true/false field called <code>featured</code>, say) to posts, then use a Card element with <strong>Posts By → Custom Field</strong>, key <code>featured</code>, value <code>1</code>. Leave the value empty to list every post where the field is filled in.</p><h2 id="rss-feeds" tabindex="-1">RSS feeds <a class="header-anchor" href="#rss-feeds" aria-label="Permalink to &quot;RSS feeds&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feed</th><th>Address</th></tr></thead><tbody><tr><td>The whole site</td><td><code>/feed</code></td></tr><tr><td>A category</td><td><code>/category/{slug}/feed</code></td></tr><tr><td>A tag</td><td><code>/tag/{slug}/feed</code></td></tr><tr><td>Another language</td><td>add <code>?lang=bn</code></td></tr></tbody></table><p>Each page links its feed in the <code>&lt;head&gt;</code>, so browsers and feed readers find it. Under <strong>Settings → RSS Feeds</strong>, choose the post types, the number of stories and whether a story shows its summary or its full text.</p><p>To check a feed, open <code>/feed</code> in the browser, paste its address into the <a href="https://validator.w3.org/feed/" target="_blank" rel="noreferrer">W3C Feed Validator</a>, or add it to a reader such as Feedly. A new story shows up within ten minutes.</p><h2 id="google-news-sitemap" tabindex="-1">Google News sitemap <a class="header-anchor" href="#google-news-sitemap" aria-label="Permalink to &quot;Google News sitemap&quot;">​</a></h2><p><code>/news-sitemap.xml</code> lists the stories published in the last 48 hours in the format Google News reads, with each story&#39;s language. It is added to <code>robots.txt</code> for you. Submit it in Google Search Console under <strong>Sitemaps</strong>, and register your publication in the Google News Publisher Center.</p><p>Under <strong>SEO → Settings → Google News sitemap</strong> you can set the publication name (exactly as Google News knows it) and limit the sitemap to news categories, leaving out sections such as recipes.</p><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p>Most Viewed is shown to whoever can see Analytics. RSS Feeds needs the Settings permission, the Google News box the SEO settings permission.</p>',29))])}const S=a(h,[["render",g]]);export{f as __pageData,S as default};
